int maxOfThree(int a, int b, int c) {
    if (a >= b && a >= c) return a;   // a beats BOTH others
    else if (b >= c)      return b;   // a lost, so it is b vs c
    else                  return c;
}

bool isTriangle(int a, int b, int c) {
    if (a <= 0 || b <= 0 || c <= 0) return false;   // degenerate sides
    return (a + b > c) && (a + c > b) && (b + c > a);
}

long long factorial(int n) {
    long long result = 1;      // multiplying by 1 changes nothing
    for (int i = 2; i <= n; ++i)
        result *= i;
    return result;             // 0! and 1! both fall out as 1
}

