long long reverseNumber(long long n) {
    bool negative = n < 0;
    if (negative) n = -n;
    long long rev = 0;
    while (n > 0) {
        rev = rev * 10 + n % 10;   // shift left, append last digit
        n /= 10;                   // chop the digit we just used
    }
    return negative ? -rev : rev;
}

bool isPalindrome(int n) {
    if (n < 0) return false;        // the minus sign never mirrors
    long long rev = 0, copy = n;
    while (copy > 0) {
        rev = rev * 10 + copy % 10;
        copy /= 10;
    }
    return rev == n;
}

int sumOfDigits(long long n) {
    if (n < 0) n = -n;
    int sum = 0;
    while (n > 0) {
        sum += (int)(n % 10);   // collect the digit
        n /= 10;                // discard it
    }
    return sum;
}

string solidRectangle(int R, int C) {
    string out;
    for (int r = 1; r <= R; ++r) {
        for (int c = 1; c <= C; ++c) out += '*';
        out += '\n';
    }
    return out;
}

string hollowRectangle(int R, int C) {
    string out;
    for (int r = 1; r <= R; ++r) {
        for (int c = 1; c <= C; ++c)
            out += (r == 1 || r == R || c == 1 || c == C) ? '*' : ' ';
        out += '\n';
    }
    return out;
}

