def solid_rectangle(R: int, C: int) -> str:
    rows = []
    for _ in range(1, R + 1):
        rows.append('*' * C)
    return '\n'.join(rows) + '\n'


def hollow_rectangle(R: int, C: int) -> str:
    rows = []
    for r in range(1, R + 1):
        row = ''.join('*' if (r == 1 or r == R or c == 1 or c == C) else ' '
                      for c in range(1, C + 1))
        rows.append(row)
    return '\n'.join(rows) + '\n'

