string halfPyramid(int n) {
    string out;
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= r; ++c) out += '*';
        out += '\n';
    }
    return out;
}

string fullPyramid(int n) {
    string out;
    for (int r = 1; r <= n; ++r) {
        out.append(n - r, ' ');        // leading spaces shrink as r grows
        out.append(2 * r - 1, '*');    // stars are the odd numbers 1,3,5,...
        out += '\n';
    }
    return out;
}

