def half_pyramid(n: int) -> str:
    return ''.join('*' * r + '\n' for r in range(1, n + 1))


def full_pyramid(n: int) -> str:
    rows = []
    for r in range(1, n + 1):
        rows.append(' ' * (n - r)      # leading spaces shrink as r grows
                    + '*' * (2 * r - 1))   # stars are the odd numbers 1,3,5,...
    return '\n'.join(rows) + '\n'

