bool isPrime(int n) {
    if (n <= 1) return false;              // 0, 1 and negatives are not prime
    if (n <= 3) return true;               // 2 and 3 are
    if (n % 2 == 0) return false;          // no other even is
    for (int i = 3; (long long)i * i <= n; i += 2)
        if (n % i == 0) return false;      // a clean division ends it
    return true;
}

